{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required case field')
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('invalid case field type')
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError('required_symbols must contain strings')

    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError('node must be an object')
        for field in ('id', 'parent', 'symbol', 'depth', 'removable', 'utility'):
            if field not in node:
                raise ValueError('missing required node field')
        node_id = node['id']
        parent = node['parent']
        depth = node['depth']
        utility = node['utility']
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError('node ids must be unique strings')
        if parent is not None and not isinstance(parent, str):
            raise ValueError('parent must be a string or null')
        if not isinstance(node['symbol'], str):
            raise ValueError('symbol must be a string')
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError('depth must be a nonnegative integer')
        if not isinstance(node['removable'], bool):
            raise ValueError('removable must be boolean')
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('utility must be finite')
        by_id[node_id] = node

    roots = [node for node in nodes if node['parent'] is None]
    if len(roots) != 1 or roots[0]['depth'] != 0:
        raise ValueError('tree must have one depth-zero root')
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            if parent not in by_id or node['depth'] != by_id[parent]['depth'] + 1:
                raise ValueError('invalid tree parent relation')

    required = set(required_symbols)
    if not required.issubset({node['symbol'] for node in nodes}):
        raise ValueError('required symbol is absent')

    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node['depth'], node['id']))
    for node in candidates:
        node_id = node['id']
        if (not node['removable'] or node['parent'] is None or
                node['symbol'] in required):
            continue
        if any(other['parent'] == node_id and other['id'] in retained for other in nodes):
            continue
        tentative = retained - {node_id}
        if all(any(by_id[other_id]['symbol'] == symbol for other_id in tentative)
               for symbol in required):
            retained = tentative
            removed.append(node_id)

    return {
        'removed_node_ids': removed,
        'retained_node_ids': sorted(retained),
    }
"}
